CREATE TABLE "c_Assignment" ("id" BIGINT NOT NULL, "a_Assignment_points" BIGINT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Course" ("id" BIGINT NOT NULL, "a_Course_code" TEXT NOT NULL, "a_Course_title" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Faculty" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Faculty_rank" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Faculty')));
CREATE TABLE "c_Person" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Person_name" TEXT NOT NULL, "a_Person_email" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Faculty','Person','Student')));
CREATE TABLE "c_Section" ("id" BIGINT NOT NULL, "a_Section_term" TEXT NOT NULL, "r_FacultySections_source_id" BIGINT, "r_FacultySections_source_dtype" TEXT, PRIMARY KEY ("id"), CHECK ("r_FacultySections_source_dtype" IS NULL OR "r_FacultySections_source_dtype" IN ('Faculty')), CHECK ((TRUE) OR "r_FacultySections_source_id" IS NULL), CHECK (NOT (TRUE) OR "r_FacultySections_source_id" IS NOT NULL));
CREATE TABLE "c_Student" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Student_student_no" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Student')));
CREATE TABLE "c_Submission" ("id" BIGINT NOT NULL, "a_Submission_submitted_at" TIMESTAMP NOT NULL, "a_Submission_score" DOUBLE PRECISION, PRIMARY KEY ("id"));
CREATE TABLE "l_AssignmentSubmissions" ("r_AssignmentSubmissions_source_id" BIGINT NOT NULL, "r_AssignmentSubmissions_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_AssignmentSubmissions_source_id", "r_AssignmentSubmissions_target_id"), UNIQUE ("r_AssignmentSubmissions_target_id"));
CREATE TABLE "l_CourseSections" ("r_CourseSections_source_id" BIGINT NOT NULL, "r_CourseSections_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_CourseSections_source_id", "r_CourseSections_target_id"), UNIQUE ("r_CourseSections_target_id"));
CREATE TABLE "l_SectionAssignments" ("r_SectionAssignments_source_id" BIGINT NOT NULL, "r_SectionAssignments_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_SectionAssignments_source_id", "r_SectionAssignments_target_id"), UNIQUE ("r_SectionAssignments_target_id"));
CREATE TABLE "l_StudentSections" ("r_StudentSections_source_id" BIGINT NOT NULL, "r_StudentSections_source_dtype" TEXT NOT NULL, "r_StudentSections_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_StudentSections_source_id", "r_StudentSections_target_id"), CHECK ("r_StudentSections_source_dtype" IS NULL OR "r_StudentSections_source_dtype" IN ('Student')));
ALTER TABLE "c_Faculty" ADD CONSTRAINT "fk_c_Faculty_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Section" ADD CONSTRAINT "fk_c_Section_0" FOREIGN KEY ("r_FacultySections_source_id", "r_FacultySections_source_dtype") REFERENCES "c_Faculty" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "c_Student" ADD CONSTRAINT "fk_c_Student_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Person" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_AssignmentSubmissions" ADD CONSTRAINT "fk_l_AssignmentSubmissions_0" FOREIGN KEY ("r_AssignmentSubmissions_source_id") REFERENCES "c_Assignment" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_AssignmentSubmissions" ADD CONSTRAINT "fk_l_AssignmentSubmissions_1" FOREIGN KEY ("r_AssignmentSubmissions_target_id") REFERENCES "c_Submission" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CourseSections" ADD CONSTRAINT "fk_l_CourseSections_0" FOREIGN KEY ("r_CourseSections_source_id") REFERENCES "c_Course" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_CourseSections" ADD CONSTRAINT "fk_l_CourseSections_1" FOREIGN KEY ("r_CourseSections_target_id") REFERENCES "c_Section" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SectionAssignments" ADD CONSTRAINT "fk_l_SectionAssignments_0" FOREIGN KEY ("r_SectionAssignments_source_id") REFERENCES "c_Section" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_SectionAssignments" ADD CONSTRAINT "fk_l_SectionAssignments_1" FOREIGN KEY ("r_SectionAssignments_target_id") REFERENCES "c_Assignment" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_StudentSections" ADD CONSTRAINT "fk_l_StudentSections_0" FOREIGN KEY ("r_StudentSections_source_id", "r_StudentSections_source_dtype") REFERENCES "c_Student" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_StudentSections" ADD CONSTRAINT "fk_l_StudentSections_1" FOREIGN KEY ("r_StudentSections_target_id") REFERENCES "c_Section" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_AssignmentSubmissions"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Submission" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_AssignmentSubmissions" l WHERE l."r_AssignmentSubmissions_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: AssignmentSubmissions'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_AssignmentSubmissions_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Submission" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_AssignmentSubmissions"();
CREATE CONSTRAINT TRIGGER "ct_AssignmentSubmissions_link" AFTER INSERT OR UPDATE OR DELETE ON "l_AssignmentSubmissions" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_AssignmentSubmissions"();
CREATE FUNCTION "require_CourseSections"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Section" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_CourseSections" l WHERE l."r_CourseSections_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: CourseSections'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_CourseSections_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Section" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CourseSections"();
CREATE CONSTRAINT TRIGGER "ct_CourseSections_link" AFTER INSERT OR UPDATE OR DELETE ON "l_CourseSections" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_CourseSections"();
CREATE FUNCTION "require_SectionAssignments"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Assignment" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_SectionAssignments" l WHERE l."r_SectionAssignments_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: SectionAssignments'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_SectionAssignments_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Assignment" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_SectionAssignments"();
CREATE CONSTRAINT TRIGGER "ct_SectionAssignments_link" AFTER INSERT OR UPDATE OR DELETE ON "l_SectionAssignments" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_SectionAssignments"();